package io.github.diodeme.ji.session.model;

import static io.github.diodeme.ji.session.model.CanonicalSessionState.RunPauseReason.HOST_RESTART;
import static io.github.diodeme.ji.session.model.CanonicalSessionState.RunStatus.PAUSED;
import static io.github.diodeme.ji.session.model.CanonicalSessionState.RunStatus.RUNNING;

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

/** Pure restart recovery transitions with retry-contract enforcement. */
public final class Recovery {
    private Recovery() {}

    public static CanonicalSessionState pauseAfterRestart(CanonicalSessionState state) {
        Optional<CanonicalSessionState.Run> pausedRun = state.activeRun().map(run ->
                run.status() == PAUSED ? run : pause(run));
        List<CanonicalSessionState.Compaction> pausedCompactions = pauseCompactions(state.compactions());
        if (pausedRun.equals(state.activeRun()) && pausedCompactions.equals(state.compactions())) return state;
        return new CanonicalSessionState(
                state.sessionId(), state.status(), state.outcome(), increment(state.revision()),
                pausedRun, state.completedRuns(), pausedCompactions);
    }

    private static CanonicalSessionState.Run pause(CanonicalSessionState.Run run) {
        var turns = new ArrayList<>(run.turns());
        if (!turns.isEmpty() && turns.getLast().status() != CanonicalSessionState.TurnStatus.TERMINAL) {
            turns.set(turns.size() - 1, pause(turns.getLast()));
        }
        CanonicalSessionState.RunPauseReason reason = run.status() == CanonicalSessionState.RunStatus.CANCELLING
                ? CanonicalSessionState.RunPauseReason.CANCELLATION_PENDING : HOST_RESTART;
        return new CanonicalSessionState.Run(
                run.id(), run.sessionId(), PAUSED, Optional.empty(), Optional.of(reason),
                increment(run.revision()), turns, run.startedAt(), Optional.empty());
    }

    public static CanonicalSessionState resume(
            CanonicalSessionState state,
            CanonicalSessionState.AttemptId attemptId,
            String resultEntryId) {
        CanonicalSessionState.Run run = state.activeRun().orElseThrow(() -> new IllegalStateException("no paused run to resume"));
        if (run.status() != PAUSED || run.pauseReason().orElse(null) != HOST_RESTART || run.turns().isEmpty()) {
            throw new IllegalStateException("only a host-restart-paused run with a current turn can resume");
        }
        var turns = new ArrayList<>(run.turns());
        CanonicalSessionState.Turn turn = turns.getLast();
        if (turn.status() != CanonicalSessionState.TurnStatus.PAUSED) throw new IllegalStateException("current turn is not paused");
        CanonicalSessionState.Turn resumed = switch (turn.pausedFrom().orElseThrow()) {
            case MODEL_STREAMING -> resumeModel(turn, attemptId, resultEntryId);
            case WAITING_FOR_TOOLS -> resumeTool(turn, attemptId);
        };
        turns.set(turns.size() - 1, resumed);
        CanonicalSessionState.Run resumedRun = new CanonicalSessionState.Run(
                run.id(), run.sessionId(), RUNNING, Optional.empty(), Optional.empty(),
                increment(run.revision()), turns, run.startedAt(), Optional.empty());
        return new CanonicalSessionState(
                state.sessionId(), state.status(), state.outcome(), increment(state.revision()),
                Optional.of(resumedRun), state.completedRuns(), state.compactions());
    }

    public static CanonicalSessionState resumeCompaction(
            CanonicalSessionState state,
            CanonicalSessionState.CompactionId compactionId,
            CanonicalSessionState.AttemptId attemptId,
            String resultEntryId,
            long expectedRevision) {
        var compactions = new ArrayList<>(state.compactions());
        int index = -1;
        for (int candidate = 0; candidate < compactions.size(); candidate++) {
            if (compactions.get(candidate).id().equals(compactionId)) {
                index = candidate;
                break;
            }
        }
        if (index < 0) throw new IllegalStateException("compaction does not exist");
        CanonicalSessionState.Compaction compaction = compactions.get(index);
        if (compaction.revision() != expectedRevision) throw new IllegalStateException("compaction revision conflict");
        if (compaction.status() != CanonicalSessionState.CompactionStatus.PAUSED) {
            throw new IllegalStateException("only paused compaction may resume");
        }
        var attempts = new ArrayList<>(compaction.attempts());
        CanonicalSessionState.Attempt previous = attempts.getLast();
        attempts.set(attempts.size() - 1, previous.supersede(previous.revision()));
        attempts.add(new CanonicalSessionState.Attempt(
                attemptId, compaction.id().value(), previous.number() + 1,
                CanonicalSessionState.AttemptStep.COMPACTION, CanonicalSessionState.AttemptStatus.RUNNING,
                Optional.empty(), 0, resultEntryId));
        CanonicalSessionState.Compaction resumed = compaction.transition(
                CanonicalSessionState.CompactionStatus.RUNNING, Optional.empty(), attempts,
                Optional.empty(), expectedRevision);
        compactions.set(index, resumed);
        return new CanonicalSessionState(
                state.sessionId(), state.status(), state.outcome(), increment(state.revision()),
                state.activeRun(), state.completedRuns(), compactions);
    }

    private static CanonicalSessionState.Turn pause(CanonicalSessionState.Turn turn) {
        CanonicalSessionState.TurnPhase phase = switch (turn.status()) {
            case MODEL_STREAMING -> CanonicalSessionState.TurnPhase.MODEL_STREAMING;
            case WAITING_FOR_TOOLS -> CanonicalSessionState.TurnPhase.WAITING_FOR_TOOLS;
            default -> throw new IllegalStateException("only active turn may pause after restart");
        };
        List<CanonicalSessionState.Attempt> attempts = turn.attempts().stream().map(attempt ->
                attempt.status() == CanonicalSessionState.AttemptStatus.RUNNING ? attempt.pause(attempt.revision()) : attempt).toList();
        List<CanonicalSessionState.ToolExecution> tools = turn.tools().stream().map(Recovery::pause).toList();
        return new CanonicalSessionState.Turn(
                turn.id(), turn.runId(), turn.number(), CanonicalSessionState.TurnStatus.PAUSED,
                Optional.empty(), Optional.of(phase), increment(turn.revision()), attempts, tools, turn.permissions());
    }

    private static CanonicalSessionState.ToolExecution pause(CanonicalSessionState.ToolExecution tool) {
        if (tool.status() == CanonicalSessionState.ToolStatus.TERMINAL
                || tool.status() == CanonicalSessionState.ToolStatus.PAUSED) return tool;
        var attempts = new ArrayList<>(tool.attempts());
        CanonicalSessionState.Attempt current = attempts.getLast();
        if (current.status() == CanonicalSessionState.AttemptStatus.RUNNING) {
            attempts.set(attempts.size() - 1, current.pause(current.revision()));
        }
        return new CanonicalSessionState.ToolExecution(
                tool.id(), tool.sessionId(), tool.runId(), tool.turnId(), tool.toolCallId(), tool.toolName(),
                tool.resultEntryId(), attempts, tool.retryContract(), tool.resumeToken(),
                CanonicalSessionState.ToolStatus.PAUSED, Optional.empty(), increment(tool.revision()));
    }

    private static CanonicalSessionState.Turn resumeModel(
            CanonicalSessionState.Turn turn, CanonicalSessionState.AttemptId attemptId, String resultEntryId) {
        var attempts = new ArrayList<>(turn.attempts());
        CanonicalSessionState.Attempt previous = attempts.getLast();
        CanonicalSessionState.Attempt closed = previous.supersede(previous.revision());
        attempts.set(attempts.size() - 1, closed);
        attempts.add(new CanonicalSessionState.Attempt(
                attemptId, turn.id().value(), previous.number() + 1, previous.step(), CanonicalSessionState.AttemptStatus.RUNNING,
                Optional.empty(), 0, resultEntryId));
        return new CanonicalSessionState.Turn(
                turn.id(), turn.runId(), turn.number(), CanonicalSessionState.TurnStatus.MODEL_STREAMING,
                Optional.empty(), Optional.empty(), increment(turn.revision()), attempts, turn.tools(), turn.permissions());
    }

    private static CanonicalSessionState.Turn resumeTool(
            CanonicalSessionState.Turn turn, CanonicalSessionState.AttemptId attemptId) {
        List<CanonicalSessionState.ToolExecution> paused = turn.tools().stream()
                .filter(tool -> tool.status() == CanonicalSessionState.ToolStatus.PAUSED).toList();
        if (paused.size() != 1 || !paused.getFirst().mayResume()) {
            throw new IllegalStateException("paused tool is not safely retryable or resumable");
        }
        CanonicalSessionState.ToolExecution target = paused.getFirst();
        var attempts = new ArrayList<>(target.attempts());
        CanonicalSessionState.Attempt prior = attempts.getLast();
        attempts.set(attempts.size() - 1, prior.supersede(prior.revision()));
        attempts.add(new CanonicalSessionState.Attempt(
                attemptId, target.id().value(), prior.number() + 1, CanonicalSessionState.AttemptStep.TOOL,
                CanonicalSessionState.AttemptStatus.RUNNING, Optional.empty(), 0, target.resultEntryId()));
        CanonicalSessionState.ToolExecution resumedTool = new CanonicalSessionState.ToolExecution(
                target.id(), target.sessionId(), target.runId(), target.turnId(), target.toolCallId(), target.toolName(),
                target.resultEntryId(), attempts, target.retryContract(), target.resumeToken(),
                CanonicalSessionState.ToolStatus.PREPARED, Optional.empty(), increment(target.revision()));
        List<CanonicalSessionState.ToolExecution> tools = turn.tools().stream()
                .map(tool -> tool.id().equals(target.id()) ? resumedTool : tool).toList();
        return new CanonicalSessionState.Turn(
                turn.id(), turn.runId(), turn.number(), CanonicalSessionState.TurnStatus.WAITING_FOR_TOOLS,
                Optional.empty(), Optional.empty(), increment(turn.revision()), turn.attempts(), tools, turn.permissions());
    }

    private static List<CanonicalSessionState.Compaction> pauseCompactions(List<CanonicalSessionState.Compaction> compactions) {
        return compactions.stream().map(compaction -> {
            if (compaction.status() != CanonicalSessionState.CompactionStatus.RUNNING) return compaction;
            var attempts = new ArrayList<>(compaction.attempts());
            CanonicalSessionState.Attempt current = attempts.getLast();
            attempts.set(attempts.size() - 1, current.pause(current.revision()));
            return new CanonicalSessionState.Compaction(
                    compaction.id(), compaction.sessionId(), CanonicalSessionState.CompactionStatus.PAUSED,
                    Optional.empty(), increment(compaction.revision()), attempts, Optional.empty());
        }).toList();
    }

    private static long increment(long value) {
        try { return Math.incrementExact(value); }
        catch (ArithmeticException exception) { throw new IllegalStateException("revision exhausted", exception); }
    }
}

